{
  "id": "R1",
  "summary_ko": "주황색 셔츠를 입은 여성이 사람들 뒤로 달리다가 완전히 사라져 다시 나타나지 않는다.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "the woman in the orange shirt completely disappears while running behind people and never shows up again",
      "symptom_ko": "주황색 셔츠를 입은 여성이 사람들 뒤로 달리다가 완전히 사라진 뒤 다시 나타나지 않음",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "the woman in the orange shirt",
      "explicit_detail_evidence": [
        "completely disappears",
        "never shows up again"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "가장 앞쪽에 있는 깃발이 파란색에서 결국 전체 빨간색으로 색상과 모양이 계속 변함",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "the flag that is the closest to the front keeps changing colors and shapes, between blue to eventually all red",
      "symptom_ko": "가장 앞쪽에 있는 깃발의 색상과 모양이 파란색에서 결국 전체 빨간색으로 계속 변함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "the flag that is the closest to the front",
      "explicit_detail_evidence": [
        "keeps changing colors and shapes",
        "between blue to eventually all red"
      ],
      "missing_details_ko": ""
    }
  ]
}

